package com.yeyamo_mobile.api.booking_service.infrastructure.web;
import static com.yeyamo_mobile.api.booking_service.application.AdminBookingDtos.*;import java.time.Instant;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import com.yeyamo_mobile.api.booking_service.application.*;import com.yeyamo_mobile.api.booking_service.application.BookingDtos.*;import com.yeyamo_mobile.api.booking_service.domain.*;import jakarta.validation.Valid;
@RestController@RequestMapping("/api/v1/booking-management/bookings")public class AdminBookingController{private final AdminBookingService service;public AdminBookingController(AdminBookingService s){service=s;}@GetMapping@PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN','SUPPORT')")public Page<AdminBookingSummary>list(@RequestParam(required=false)String search,@RequestParam(required=false)BookingStatus status,@RequestParam(required=false)String userId,@RequestParam(required=false)String partnerId,@RequestParam(required=false)String placeId,@RequestParam(required=false)String eventId,@RequestParam(required=false)PaymentStatus paymentStatus,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant createdFrom,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant createdTo,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant bookingDateFrom,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant bookingDateTo,Pageable pageable){return service.list(search,status,userId,partnerId,placeId,eventId,paymentStatus,createdFrom,createdTo,bookingDateFrom,bookingDateTo,pageable);}@GetMapping("/stats")@PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN','SUPPORT')")public AdminBookingStats stats(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant to){return service.stats(from,to);}@GetMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN','SUPPORT')")public AdminBookingDetail detail(@PathVariable UUID id){return service.detail(id);}@PostMapping("/{id}/cancel")@PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN')")public BookingView cancel(Authentication auth,@PathVariable UUID id,@Valid@RequestBody CancelBooking body,@RequestHeader("Idempotency-Key")String key,@RequestHeader(value="X-Correlation-Id",required=false)String correlation){return service.cancel(auth.getName(),id,body.reason(),key,correlation);}@PostMapping("/{id}/complete")@PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN')")public BookingView complete(Authentication auth,@PathVariable UUID id,@RequestHeader("Idempotency-Key")String key,@RequestHeader(value="X-Correlation-Id",required=false)String correlation){return service.complete(auth.getName(),id,key,correlation);}}
